import sqlite3
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)

app = Flask(__name__)

DATABASE_NAME = 'database.db'

def get_db_connection():
    conn = sqlite3.connect(DATABASE_NAME)
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/items', methods=['POST'])
def create_item():
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    name = data['name']
    try:
        with get_db_connection() as conn:
            cursor = conn.cursor()
            cursor.execute('INSERT INTO items (name) VALUES (?)', (name,))
            conn.commit()
            logging.info(f""Created item: {name}"")
        return jsonify({'message': 'Item created successfully'}), 201
    except Exception as e:
        logging.error(f""Error creating item: {e}"")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/items', methods=['GET'])
def read_items():
    try:
        with get_db_connection() as conn:
            items = conn.execute('SELECT * FROM items').fetchall()
            logging.info(""Retrieved all items"")
        return jsonify([dict(item) for item in items]), 200
    except Exception as e:
        logging.error(f""Error reading items: {e}"")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/items/<int:item_id>', methods=['GET'])
def read_item(item_id):
    try:
        with get_db_connection() as conn:
            item = conn.execute('SELECT * FROM items WHERE id = ?', (item_id,)).fetchone()
            if item is None:
                return jsonify({'error': 'Item not found'}), 404
            logging.info(f""Retrieved item: {item['id']}"")
        return jsonify(dict(item)), 200
    except Exception as e:
        logging.error(f""Error reading item with id {item_id}: {e}"")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/items/<int:item_id>', methods=['PUT'])
def update_item(item_id):
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    name = data['name']
    try:
        with get_db_connection() as conn:
            result = conn.execute('UPDATE items SET name = ? WHERE id = ?', (name, item_id))
            if result.rowcount == 0:
                return jsonify({'error': 'Item not found'}), 404
            conn.commit()
            logging.info(f""Updated item: {item_id}"")
        return jsonify({'message': 'Item updated successfully'}), 200
    except Exception as e:
        logging.error(f""Error updating item with id {item_id}: {e}"")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/items/<int:item_id>', methods=['DELETE'])
def delete_item(item_id):
    try:
        with get_db_connection() as conn:
            result = conn.execute('DELETE FROM items WHERE id = ?', (item_id,))
            if result.rowcount == 0:
                return jsonify({'error': 'Item not found'}), 404
            conn.commit()
            logging.info(f""Deleted item: {item_id}"")
        return jsonify({'message': 'Item deleted successfully'}), 200
    except Exception as e:
        logging.error(f""Error deleting item with id {item_id}: {e}"")
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    with sqlite3.connect(DATABASE_NAME) as conn:
        conn.execute('CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY, name TEXT)')
    app.run(debug=True)
