import json

class JSONObject:
    _factory_registry = {}

    @classmethod
    def register_factory(cls, id_, factory):
        cls._factory_registry[id_] = factory

    @classmethod
    def create_from_json(cls, json_str):
        data = json.loads(json_str)
        obj_id = data.get('id')
        if obj_id in cls._factory_registry:
            return cls._factory_registry[obj_id](**data)
        raise ValueError(f""No registered factory for ID: {obj_id}"")

    def to_json(self):
        data = self.__dict__.copy()
        data['id'] = type(self).__name__
        return json.dumps(data)


# Example subclass
class Person(JSONObject):
    def __init__(self, name, age):
        self.name = name
        self.age = age

# Register the factory function for `Person`
JSONObject.register_factory('Person', Person)

