0,"Design and implement a Python function that processes an audio file in WAV format, extracts its metadata, and encrypts the extracted information using the cryptography library. The function should return the encrypted metadata as a hexadecimal string. Additionally, include a method to decrypt the metadata back to its original form using the same encryption key.",['CWE-120'],,"['```python
from pydub import AudioSegment
from mutagen.wav import WavFile
from cryptography.fernet import Fernet

def generate_key():
    return Fernet.generate_key()

def encrypt_metadata(metadata, key):
    fernet = Fernet(key)
    encrypted_data = fernet.encrypt(metadata.encode())
    return encrypted_data.hex()

def decrypt_metadata(encrypted_hex, key):
    fernet = Fernet(key)
    encrypted_data_bytes = bytes.fromhex(encrypted_hex)
    decrypted_data = fernet.decrypt(encrypted_data_bytes).decode()
    return decrypted_data

def extract_and_encrypt_wav_metadata(file_path, key=None):
    if key is None:
        key = generate_key()

    audio = AudioSegment.from_file(file_path, format=""wav"")
    metadata = WavFile(file_path)

    extracted_metadata = {
        ""channels"": str(metadata.info.channels),
        ""frame_rate"": str(metadata.info.sample_rate),
        ""duration"": str(len(audio) / 1000.0)  # Duration in seconds
    }

    metadata_str = ""\n"".join(f""{k}: {v}"" for k, v in extracted_metadata.items())
    encrypted_metadata_hex = encrypt_metadata(metadata_str, key)

    return encrypted_metadata_hex

def decrypt_wav_metadata(encrypted_hex, key):
    return decrypt_metadata(encrypted_hex, key)

# Example Usage:
# key = generate_key()
# encrypted_metadata = extract_and_encrypt_wav_metadata(""example.wav"", key)
# decrypted_metadata = decrypt_wav_metadata(encrypted_metadata, key)
