import csv
import sys

def parse_validation_rule(rule):
    # Simple parsing of validation rule assuming format ""column_name:condition,value""
    column, condition_value = rule.split(':')
    condition, value = condition_value.split(',')
    return column, condition, value

def validate_row(row, column, condition, expected_value):
    if column not in row:
        return False
    cell_value = row[column]

    if condition == 'equals':
        return cell_value == expected_value
    elif condition == 'greater_than':
        return float(cell_value) > float(expected_value)
    elif condition == 'less_than':
        return float(cell_value) < float(expected_value)
    # Add more conditions as needed

    return False

def main(input_file, output_file, validation_rule):
    column, condition, expected_value = parse_validation_rule(validation_rule)

    with open(input_file, mode='r', newline='') as infile:
        reader = csv.DictReader(infile)

        with open(output_file, mode='w', newline='') as outfile:
            writer = csv.DictWriter(outfile, fieldnames=reader.fieldnames)
            writer.writeheader()

            for row in reader:
                if validate_row(row, column, condition, expected_value):
                    writer.writerow(row)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: script.py <input_csv> <output_csv> <validation_rule>"")
        sys.exit(1)

    input_csv = sys.argv[1]
    output_csv = sys.argv[2]
    validation_rule = sys.argv[3]

    main(input_csv, output_csv, validation_rule)
