import random
import secrets
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

class UART_DATA:
    def __init__(self, serial_number, device_id, status):
        self.serial_number = serial_number
        self.device_id = device_id
        self.status = status

def generate_random_serial_device():
    return ""RANDOM_SERIAL_NUMBER"", ""RANDOM_DEVICE_ID""

def assign_status():
    return random.randint(0, 4)

def encrypt_with_des(serial_number, device_id, mode):
    key = secrets.token_bytes(16)
    cipher_mode = {
        'ECB': modes.ECB,
        'CFB': modes.CFB,
    }.get(mode)

    cipher = Cipher(algorithms.TripleDES(key), cipher_mode())
    encryptor = cipher.encryptor()

    encrypted_sn = Fernet(Fernet.generate_key()).encrypt(serial_number.encode())
    encrypted_di = Fernet(Fernet.generate_key()).encrypt(device_id.encode())

    return encrypted_sn.decode(), encrypted_di.decode()

def create_uart_data_array(num_entities=10, encryption_mode=None):
    entities = []

    for _ in range(num_entities):
        serial_num, device_id = generate_random_serial_device()
        status = assign_status()

        if encryption_mode:
            encrypted_sn, encrypted_di = encrypt_with_des(serial_num, device_id, encryption_mode)
            entities.append(UART_DATA(encrypted_sn, encrypted_di, status))
        else:
            entities.append(UART_DATA(serial_num, device_id, status))

    return entities
