import ctypes

def calculate_average(file_path):
    """"""Calculate the average of numbers in a file until -99 is encountered.""""""
    try:
        with open(file_path, 'r') as f:
            total = 0.0
            count = 0
            while True:
                line = f.readline()
                if not line or '-99' in line:
                    break
                try:
                    number = float(line.strip())
                    total += number
                    count += 1
                except ValueError:
                    continue
        return total / count if count > 0 else None
    except IOError:
        print(""Error reading file."")
        return None

# Load the C module (compiled with Cython)
arithmetic_module = ctypes.CDLL('./arithmetic.so')

def perform_operation(operation, a, b):
    """"""Perform an arithmetic operation using the C extension.""""""
    try:
        if operation == 'add':
            result = arithmetic_module.add(a, b)
        elif operation == 'subtract':
            result = arithmetic_module.subtract(a, b)
        elif operation == 'multiply':
            result = arithmetic_module.multiply(a, b)
        elif operation == 'divide':
            result = arithmetic_module.divide(a, b)
        else:
            raise ValueError(""Invalid operation"")

        if result is not None:
            return ctypes.c_double(result).value
    except Exception as e:
        print(f""Operation error: {e}"")
        return None

# Example usage
