import os
import time
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad
from Crypto.Random import get_random_bytes

class CryptoMessage:
    def __init__(self, encrypted_content, status, message_id, metadata=None):
        self.encrypted_content = encrypted_content
        self.status = status
        self.message_id = message_id
        self.metadata = metadata or {}

class CryptoMessageEncoder:
    def __init__(self, key_length=16, mode='CBC'):
        self.key_length = key_length
        self.mode = mode
        self.key = get_random_bytes(self.key_length)

    def generate_encrypted_messages(self, data_array):
        messages = []
        for idx, data in enumerate(data_array):
            content = f""ID: {data['device_id']}, Status: {data['status']}""
            encrypted_content = self.encrypt(content.encode())
            status = os.urandom(1)[0] % 3 + 1
            message_id = idx + 1
            metadata = {
                'serial_number': data['serial_number'],
                'device_id': data['device_id']
            }
            messages.append(CryptoMessage(
                encrypted_content, 
                status, 
                message_id, 
                metadata))
        return messages

    def encrypt(self, content):
        if self.mode == 'CBC':
            iv = get_random_bytes(AES.block_size)
            cipher = AES.new(self.key, AES.MODE_CBC, iv)
            return iv + cipher.encrypt(pad(content, AES.block_size))
        elif self.mode == 'ECB':
            cipher = AES.new(self.key, AES.MODE_ECB)
            return cipher.encrypt(pad(content, AES.block_size))
        else:
            raise ValueError(""Unsupported mode"")

def create_and_populate_uart_data_array(size):
    uart_data_array = []
    for i in range(size):
        serial_number = f""SN{i + 1}""
        device_id = os.urandom(1)[0] % 100 + 1
        status = os.urandom(1)[0] % 3 + 2
        uart_data_array.append({
            'serial_number': serial_number,
            'device_id': device_id,
            'status': status
        })
    return uart_data_array

def main():
    size = 10  # Number of UART_DATA structures to create
    uart_data_array = create_and_populate_uart_data_array(size)

    encoder = CryptoMessageEncoder(key_length=16, mode='CBC')
    encrypted_messages = encoder.generate_encrypted_messages(uart_data_array)

    for message in encrypted_messages:
        print(f""ID: {message.message_id}, Status: {message.status}, Metadata: {message.metadata}"")

if __name__ == ""__main__"":
    main()
```

