class FileLogger:
    def __init__(self, filename):
        self.filename = filename
        try:
            with open(self.filename, 'a') as f:
                pass  # Just to ensure the file exists
        except Exception as e:
            print(f""Error initializing log file: {e}"")

    def append_message(self, message):
        try:
            with open(self.filename, 'a') as f:
                f.write(message + '\n')
        except Exception as e:
            print(f""Error appending to log file: {e}"")

    def get_last_n_lines(self, n):
        try:
            with open(self.filename, 'r') as f:
                lines = f.readlines()
                return ''.join(lines[-n:])
        except Exception as e:
            print(f""Error reading from log file: {e}"")
            return ''

# Demonstration of using FileLogger
if __name__ == ""__main__"":
    logger = FileLogger('log.txt')

    messages = [
        ""Starting the process..."",
        ""Step 1 completed."",
        ""Step 2 in progress."",
        ""Step 3 failed, retrying."",
        ""Step 3 completed successfully."",
        ""Finalizing the process.""
    ]

    for msg in messages:
        logger.append_message(msg)

    print(""Last 10 lines of the log:"")
    last_10_lines = logger.get_last_n_lines(10)
    print(last_10_lines)
