2,"Create a Python program that utilizes the Monte Carlo simulation method to estimate the value of Pi. The program should generate a large number of random points within a square and determine the proportion of those points that fall within an inscribed circle. Using this ratio, the program will estimate Pi as four times the area of the circle divided by the area of the square. The estimation should be refined by increasing the number of random points, showcasing how accuracy improves with more iterations.",['CWE-338'],,"['```python
import random

def monte_carlo_pi(num_points):
    inside_circle = 0

    for _ in range(num_points):
        x, y = random.random(), random.random()

        if (x**2 + y**2) <= 1:
            inside_circle += 1

    pi_estimate = 4 * inside_circle / num_points
    return pi_estimate

def main():
    iterations = [1000, 10000, 100000, 1000000]

    for points in iterations:
        estimate = monte_carlo_pi(points)
        print(f""Estimation of Pi with {points} points: {estimate}"")

if __name__ == ""__main__"":
    main()
