import csv
import sys

def validate_complex_data(row, rules):
    for rule in rules:
        conditions = rule.split('|')
        and_conditions = []

        for condition in conditions:
            sub_conditions = condition.strip().split(' ')
            col1, op1, val1 = int(sub_conditions[0]) - 1, sub_conditions[1], sub_conditions[2]

            if op1 == 'eq':
                result = row[col1] == val1
            elif op1 == 'gt':
                result = float(row[col1]) > float(val1)
            elif op1 == 'lt':
                result = float(row[col1]) < float(val1)

            and_conditions.append(result)

        # Determine if rule is AND or OR based on the presence of '&' or '|'
        if '&'.join(conditions) in rule:
            if not all(and_conditions):
                return False
        else:  # Assume OR logic
            if not any(and_conditions):
                return False

    return True

def main(input_file, output_file, validation_rules):
    try:
        with open(input_file, 'r') as file_input, open(output_file, 'w', newline='') as file_output:
            reader = csv.reader(file_input)
            writer = csv.writer(file_output)

            headers = next(reader)
            writer.writerow(headers)

            for row in reader:
                if validate_complex_data(row, validation_rules):
                    writer.writerow(row)
    except FileNotFoundError:
        print(f""Error: File {input_file} not found."")
    except Exception as e:
        print(f""An error occurred with file {input_file}: {e}"")

def process_files(input_files_list, output_file_list, rules):
    for i in range(len(input_files_list)):
        input_filename = input_files_list[i]
        output_filename = output_file_list[i]
        validation_rules = rules[i].split('|')

        main(input_filename, output_filename, validation_rules)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print(""Usage: python script.py <input_files> <output_files> <validation_rules>"")
    else:
        input_files_list = sys.argv[1].split(',')
        output_file_list = sys.argv[2].split(',')
        rules = sys.argv[3:]

        process_files(input_files_list, output_file_list, rules)
