        ip_address = generate_ip_address()
        dns_name = generate_dns_name(i)
        status_code = generate_status_code()
        response = NFA_DNS_QUERY_RESPONSE_T(ip_address, dns_name, status_code)
        responses.append(response)
    return responses

# Example usage
