from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

def create_aes_cipher(key: bytes, mode: str, iv: bytes = None) -> Cipher:
    if not key or len(key) not in (16, 24, 32):
        raise ValueError(""Invalid key size. AES requires a key of length 16, 24, or 32 bytes."")

    algorithm = algorithms.AES(key)

    if mode.upper() == 'CBC':
        if not iv or len(iv) != 16:
            raise ValueError(""CBC mode requires a 16-byte IV."")
        cipher_mode = modes.CBC(iv)
    elif mode.upper() == 'CFB':
        if not iv or len(iv) != 16:
            raise ValueError(""CFB mode requires a 16-byte IV."")
        cipher_mode = modes.CFB(iv)
    elif mode.upper() == 'OFB':
        if not iv or len(iv) != 16:
            raise ValueError(""OFB mode requires a 16-byte IV."")
        cipher_mode = modes.OFB(iv)
    elif mode.upper() == 'ECB':
        # ECB does not require an IV
        cipher_mode = None
    else:
        raise ValueError(f""Unsupported mode: {mode}"")

    return Cipher(algorithm, cipher_mode or modes.ECB(), backend=default_backend())

# Example usage (not part of the task):
# cipher = create_aes_cipher(b'mysecretkey123456', 'CBC', b'initialvector123')
