class SessionData(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, unique=True, nullable=False)
    preferences = db.Column(db.JSON, nullable=True)
    cart_contents = db.Column(db.JSON, nullable=True)
    auth_details = db.Column(db.JSON, nullable=True)

db.create_all()

def load_session(user_id):
    session_data = SessionData.query.filter_by(user_id=user_id).first()
    if not session_data:
        return None
    return {
        'preferences': session_data.preferences,
        'cart_contents': session_data.cart_contents,
        'auth_details': session_data.auth_details
    }

def update_session(user_id, action):
    session_data = SessionData.query.filter_by(user_id=user_id).first()

    if not session_data:
        # Create new session data if it doesn't exist
        session_data = SessionData(
            user_id=user_id,
            preferences={},
            cart_contents=[],
            auth_details={}
        )

    if action['type'] == 'add_to_cart':
        item = action.get('item')
        if session_data.cart_contents is None:
            session_data.cart_contents = []
        session_data.cart_contents.append(item)

    elif action['type'] == 'logout':
        session_data.auth_details = {}

    db.session.add(session_data)
    db.session.commit()

    return load_session(user_id)

@app.route('/update_session', methods=['POST'])
def handle_update():
    user_id = request.json.get('user_id')
    action = request.json.get('action')

    updated_session = update_session(user_id, action)

    if not updated_session:
        return {'error': 'Session not found'}, 404

    return updated_session

if __name__ == '__main__':
    app.run(debug=True)
```

