import paho.mqtt.client as mqtt
import json
import hashlib
import os
import time

class MQTTStateServiceManager:
    def __init__(self):
        self.FILE_PATH = ""/path/to/statefile""
        self.MESSAGE_TOPIC = ""message_topic""
        self.SERVICE_START_DELAY_MIN = 1000 / 1000.0  # In seconds
        self.SERVICE_START_DELAY_MAX = 5000 / 1000.0  # In seconds

    def load_state(self):
        try:
            with open(self.FILE_PATH, 'rb') as file:
                object_content = file.read()
            if isinstance(object_content, bytes):
                md5_digest = hashlib.md5(object_content)
                md5_hash = md5_digest.hexdigest()
                print(""MD5 Hash: "" + md5_hash)
            else:
                print(""Invalid state object type."")
        except FileNotFoundError:
            print(""State file not found."")

    def manage_services(self):
        client = mqtt.Client()

        @client.on_connect
        def on_connect(client, userdata, flags, rc):
            if rc == 0:
                print(""Connected successfully"")
                client.subscribe(self.MESSAGE_TOPIC)
            else:
                print(f""Connection failed with code {rc}"")

        @client.on_message
        def on_message(client, userdata, msg):
            message_data = json.loads(msg.payload.decode())
            with open('incoming_messages.log', 'a') as log_file:
                log_file.write(json.dumps(message_data) + '\n')
            print(f""Received message: {msg.payload.decode()}"")

        try:
            client.connect('mqtt.broker.example.com', 1883, 60)
            client.loop_start()

            for _ in range(3):
                delay_time = int.from_bytes(os.urandom(4), 'big') % (self.SERVICE_START_DELAY_MAX - self.SERVICE_START_DELAY_MIN + 1) + self.SERVICE_START_DELAY_MIN
                time.sleep(delay_time)
                client.publish(self.MESSAGE_TOPIC, json.dumps({""service"": ""start""}))

            # Keep the main thread running to maintain MQTT connection loop
            while True:
                time.sleep(10)

        except Exception as e:
            print(f""An error occurred: {e}"")

        finally:
            client.loop_stop()
            client.disconnect()

# Example usage
manager = MQTTStateServiceManager()
manager.load_state()
manager.manage_services()
