import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
import hashlib
import time

# DNS Response structure
class DNS_Response:
    def __init__(self):
        self.ipv6_address = ''
        self.hostname = ''
        self.status_code = 0

# Function to generate DNS responses with AES-256-CBC encryption
def encrypt_data(data, key):
    cipher = AES.new(key, AES.MODE_CBC)
    ct_bytes = cipher.encrypt(pad(data.encode(), AES.block_size))
    return cipher.iv + ct_bytes

def decrypt_data(encrypted_data, key):
    iv = encrypted_data[:AES.block_size]
    ct = encrypted_data[AES.block_size:]
    cipher = AES.new(key, AES.MODE_CBC, iv)
    pt = unpad(cipher.decrypt(ct), AES.block_size)
    return pt.decode()

def generate_dns_response(count):
    responses = []
    key = hashlib.sha256(b""secret_key"").digest()  # Example fixed key for encryption

    for i in range(count):
        timestamp = int(time.time())
        hostname = f""host-{timestamp // 1000}""
        status_code = (timestamp % 199) + 200

        ip_str = ''.join(['{:x}'.format((timestamp >> (8 * j)) & 0xff) for j in range(8)][::-1])
        response_ipv6_address = ':'.join([ip_str[j:j+4] for j in range(0, len(ip_str), 4)])

        dns_response = DNS_Response()
        dns_response.ipv6_address = response_ipv6_address
        dns_response.hostname = hostname
        dns_response.status_code = status_code

        encrypted_response = encrypt_data(
            json.dumps(dns_response.__dict__), key)

        responses.append(encrypted_response)

    return responses

# Merged class handling JSON objects and string modification
class StringModifierJSONHandler:
    def __init__(self):
        self.registry = {}

    def add_factory_function(self, id, factory_function):
        self.registry[id] = factory_function

    def instantiate_object(self, id, **kwargs):
        factory_function = self.registry.get(id)
        if not factory_function:
            return None
        return factory_function(**kwargs)

    def append_slash(self, input_string: str, size_limit: int) -> str | None:
        if len(input_string) <= size_limit:
            return input_string + ""/""
        else:
            return None

# Example usage of the merged class:

def create_subclass1(name):
    response_dict = {'name': name}
    return json.dumps(response_dict)

def create_subclass2(name):
    response_dict = {'name': f""{name}_v2""}
    return json.dumps(response_dict)

# Initialize the handler
handler = StringModifierJSONHandler()
handler.add_factory_function('subclass1', create_subclass1)
handler.add_factory_function('subclass2', create_subclass2)

# Generate DNS responses with encryption
