import random

def create_tr_entities(num_entities, min_pci, max_pci, min_traffic, max_traffic, rnti_sort=False):
    def is_unique_rnti(rnti_list, new_rnti):
        return new_rnti not in rnti_list

    def generate_random_rnti(existing_rntis):
        while True:
            rnti = random.randint(0x0000, 0xFFFF)
            if is_unique_rnti(existing_rntis, rnti):
                return rnti

    def generate_entity():
        pci = random.randint(min_pci, max_pci)
        rnti = generate_random_rnti(rnti_list)
        traffic = random.randint(min_traffic, max_traffic)
        return {'pci': pci,
                'rnti': rnti,
                'retransmissions': 3,
                'cell_traffic': traffic}

    tr_entities = []
    existing_rntis = []
    for _ in range(num_entities):
        tr_entity = generate_entity()
        tr_entities.append(tr_entity)
        existing_rntis.append(tr_entity['rnti'])

    if rnti_sort:
        tr_entities.sort(key=lambda x: x['rnti'])

    return tr_entities
