from cryptography.hazmat.primitives import hashes, hmac, ec
from cryptography.hazmat.primitives.asymmetric.utils import Prehashed
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.serialization import load_pem_private_key

def register_custom_primitives():
    class SHA3_256(hashes.HashAlgorithm):
        name = 'SHA3-256'
        digest_size = 32
        block_size = 136

        def new(self, data=b''):
            return hashes.Hash(SHA3_256(), backend=default_backend())

    class HMAC_Sha256_Hash(hmac.HMAC):
        hash_algorithm = hashes.SHA256()

        @classmethod
        def with_hash(cls, key, msg=None):
            return cls(key=key, msg=msg, digestmod=cls.hash_algorithm)

    class ECDSAWithP256:
        def sign(self, private_key, data):
            signature = private_key.sign(data, ec.ECDSA(Prehashed(hashes.SHA256())))
            return signature

        @staticmethod
        def verify(public_key, signature, data):
            try:
                public_key.verify(signature, data, ec.ECDSA(Prehashed(hashes.SHA256())))
                return True
            except Exception as e:
                return False

    # Registering the custom primitives with the backend or system
    default_backend().register_module('SHA3-256', SHA3_256())
    default_backend().register_module('HMAC-SHA256', HMAC_Sha256_Hash())
    default_backend().register_module('ECDSA-P256', ECDSAWithP256())

