0,"Design and implement a Python program that manages a database connection pool using the `psycopg2` library for PostgreSQL. The program should allow users to connect to a PostgreSQL database, execute read and write queries, and automatically manage the connections by reusing them from the pool. Additionally, include error handling for database connection issues and provide functions for acquiring and releasing connections from the pool.",['CWE-918'],,"['```python
import psycopg2
from psycopg2 import pool

class DatabaseConnectionPool:
    def __init__(self, minconn, maxconn, **db_params):
        self.pool = psycopg2.pool.SimpleConnectionPool(minconn, maxconn, **db_params)

    def get_connection(self):
        try:
            return self.pool.getconn()
        except (Exception, psycopg2.DatabaseError) as error:
            print(f""Error acquiring connection: {error}"")
            return None

    def release_connection(self, conn):
        try:
            if conn:
                self.pool.putconn(conn)
        except (Exception, psycopg2.DatabaseError) as error:
            print(f""Error releasing connection: {error}"")

    def execute_query(self, query, params=()):
        conn = self.get_connection()
        if not conn:
            return None

        try:
            with conn.cursor() as cursor:
                cursor.execute(query, params)
                if query.lower().startswith(""select""):
                    result = cursor.fetchall()
                    conn.commit()
                    return result
                else:
                    conn.commit()
        except (Exception, psycopg2.DatabaseError) as error:
            print(f""Error executing query: {error}"")
        finally:
            self.release_connection(conn)

    def close_all_connections(self):
        try:
            self.pool.closeall()
        except Exception as error:
            print(f""Error closing all connections: {error}"")

# Example usage
if __name__ == ""__main__"":
    db_params = {
        'dbname': 'your_db',
        'user': 'your_user',
        'password': 'your_password',
        'host': 'localhost',
        'port': 5432,
    }

    connection_pool = DatabaseConnectionPool(1, 10, **db_params)

    # Example read query
    select_query = ""SELECT * FROM your_table""
    result = connection_pool.execute_query(select_query)
    print(result)

    # Example write query
    insert_query = ""INSERT INTO your_table (column1, column2) VALUES (%s, %s)""
    connection_pool.execute_query(insert_query, ('value1', 'value2'))

    # Close all connections when done
    connection_pool.close_all_connections()
