import secrets
import hashlib

class TREntity:
    _registry = {}

    @staticmethod
    def add_factory(id):
        def decorator(func):
            TREntity._registry[id] = func
            return func

        return decorator

    @staticmethod
    def create_instance(id):
        if id not in TREntity._registry:
            raise ValueError(""Factory function with ID not found"")
        return TREntity._registry[id]()

class NFAPI_NetworkEntity(TREntity):
    def __init__(self):
        self.rx_ue_tag = secrets.randbits(64)
        self.rnti = secrets.randbits(16)
        data_to_hash = b""Sensitive Data for NFAPI entity""
        hash_algorithm = hashlib.sha256()
        hash_algorithm.update(data_to_hash)
        hashed_value = hash_algorithm.digest()
        self.crcflag = hashed_value[:1]  # First byte of SHA-256 hash

class TRFactory:
    @NFAPI_NetworkEntity.add_factory(""NFAPI"")
    def nfaapi_entity():
        return NFAPI_NetworkEntity()

