import os
from Crypto.Protocol.KDF import PBKDF2
from Crypto.Random import get_random_bytes

class KDFRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, name, factory_func):
        if not callable(factory_func):
            raise ValueError(""Factory function must be callable"")
        self._registry[name] = factory_func

    def create_kdf(self, name, password, salt_len=16, key_len=None, iterations=100000):
        if not isinstance(password, str) or not password:
            raise ValueError(""Password must be a non-empty string"")

        if name not in self._registry:
            raise ValueError(f""No factory registered under the name: {name}"")

        # Generate salt
        salt = get_random_bytes(salt_len)

        # Determine key length if not provided
        if key_len is None:
            key_len = os.urandom(1)[0] % 32 + 16  # Randomly choose a key length between 16 and 47

        # Derive key using PBKDF2
        derived_key = self._registry[name](password, salt, key_len=key_len, iterations=iterations)

        return {
            ""id"": os.urandom(16).hex(),
            ""salt"": salt.hex(),
            ""derived_key"": derived_key.hex()
        }

def pbkdf2_factory(password, salt, key_len, iterations):
    return PBKDF2(password, salt, dkLen=key_len, count=iterations)

# Example usage
registry = KDFRegistry()
registry.register('PBKDF2', pbkdf2_factory)

kdf_info = registry.create_kdf('PBKDF2', 'secure_password')
print(kdf_info)
