5. Ensure thread safety for concurrent operations without conflicts.",['CWE-680'],,"['```python
import threading
from collections import defaultdict, deque

class DAG:
    def __init__(self):
        self.graph = defaultdict(list)
        self.lock = threading.Lock()

    def add_edge(self, u, v):
        with self.lock:
            if not isinstance(u, int) or not isinstance(v, int):
                raise ValueError(""Invalid data type: Nodes must be integers."")
            self.graph[u].append(v)

    def validate_dag(self):
        visited = set()
        rec_stack = set()

        def visit(node):
            if node in rec_stack:
                return False
            if node in visited:
                return True

            visited.add(node)
            rec_stack.add(node)
            for neighbor in self.graph[node]:
                if not visit(neighbor):
                    return False
            rec_stack.remove(node)
            return True

        with self.lock:
            for node in self.graph:
                if not visit(node):
                    raise ValueError(""Cycle detected: Invalid DAG"")

    def report(self):
        with self.lock:
            total_nodes = len(self.graph)
            total_edges = sum(len(neighbors) for neighbors in self.graph.values())
            return total_nodes, total_edges

    def filter_dag(self, criterion_func):
        if not callable(criterion_func):
            raise ValueError(""Criterion must be a callable function."")

        with self.lock:
            filtered_graph = {k: [v for v in vals if criterion_func(v)] for k, vals in self.graph.items()}

        return filtered_graph

def main():
    dag = DAG()

    try:
        # Example edges
        dag.add_edge(1, 2)
        dag.add_edge(1, 3)
        dag.add_edge(3, 4)

        # Validate DAG
        dag.validate_dag()

        # Report total nodes and edges
        total_nodes, total_edges = dag.report()
        print(f""Total Nodes: {total_nodes}, Total Edges: {total_edges}"")

        # Filter DAG based on user-defined criteria
        def criterion(node):
            return node % 2 == 0

        filtered_graph = dag.filter_dag(criterion)
        print(""Filtered Graph:"", filtered_graph)

