from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt
import os
import base64

class Message:
    def __init__(self, content, encrypted=False):
        self.content = content
        self.encrypted = encrypted

class KeyManager:
    @staticmethod
    def generate_key():
        # Generate a 256-bit key for AES encryption
        return os.urandom(32)

    @staticmethod
    def validate_key(key):
        if len(key) != 32:
            raise ValueError(""Invalid key length"")

class CipherHandler:
    def __init__(self, key_manager: KeyManager):
        self.key_manager = key_manager

    def encrypt(self, message: Message, key=None):
        if not key:
            key = self.key_manager.generate_key()

        self.key_manager.validate_key(key)

        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(key), modes.CFB(iv), backend=default_backend())
        encryptor = cipher.encryptor()

        ct = encryptor.update(message.content.encode()) + encryptor.finalize()
        encrypted_message = base64.b64encode(iv + ct).decode('utf-8')

        return Message(encrypted_message, encrypted=True)

    def decrypt(self, message: Message, key):
        self.key_manager.validate_key(key)

        raw_data = base64.b64decode(message.content)
        iv = raw_data[:16]
        ct = raw_data[16:]

        cipher = Cipher(algorithms.AES(key), modes.CFB(iv), backend=default_backend())
        decryptor = cipher.decryptor()

        decrypted_message_content = (decryptor.update(ct) + decryptor.finalize()).decode('utf-8')
        return Message(decrypted_message_content, encrypted=False)

# Example usage
if __name__ == ""__main__"":
    key_manager = KeyManager()
    cipher_handler = CipherHandler(key_manager)

    messages = [
        Message(""Hello World""),
        Message(""Secret Information"", True),
        Message(""Another message"")
    ]

    # Encrypt all plaintext messages
    for msg in messages:
        if not msg.encrypted:
            encrypted_msg = cipher_handler.encrypt(msg, key_manager.generate_key())
            print(f""Encrypted: {encrypted_msg.content}"")

    # Decrypt a message (assuming we have the correct key)
    test_key = key_manager.generate_key()
    encrypted_message = cipher_handler.encrypt(Message(""Test Message""), test_key)
    decrypted_message = cipher_handler.decrypt(encrypted_message, test_key)
    print(f""Decrypted: {decrypted_message.content}"")
