#include <stdio.h>
#include <stdlib.h>
import time
from threading import Thread, Lock
import random

# Define structures
class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rnti, crcflag):
        self.RNTI = rnti
        self.CRCFLAG = crcflag


class SDR_RX_STREAM_T:
    def __init__(self, start_time, snr):
        self.StartTime = start_time
        self.SNR = snr

# Constants
RNTI_RANGE_START = 1
RNTI_RANGE_END = 100
CRCFLAG_CRITERIA = lambda x: ""PASS"" if x % 2 == 0 else ""FAIL""
SNR_MIN = -10
SNR_MAX = 30

# Lock for thread-safe operations
lock = Lock()

def generate_nfa_crc_pdu(rx_ue_info_tag, num_pdus):
    pdus = []
    for _ in range(num_pdus):
        rnti = random.randint(RNTI_RANGE_START, RNTI_RANGE_END)
        crcflag = CRCFLAG_CRITERIA(rnti)
        try:
            pdu = NFAPI_CRC_INDICATION_PDU_T(rnti, crcflag)
            with lock:
                pdus.append((rx_ue_info_tag, pdu))
        except MemoryError:
            print(f""Memory allocation failed for RNTI: {rnti}"")
    return pdus

def generate_sdr_rx_stream(rx_ue_info_tag, num_streams):
    streams = []
    for _ in range(num_streams):
        start_time = int(time.time())
        snr = random.uniform(SNR_MIN, SNR_MAX)
        try:
            stream = SDR_RX_STREAM_T(start_time, snr)
            with lock:
                streams.append((rx_ue_info_tag, stream))
        except MemoryError:
            print(f""Memory allocation failed for start time: {start_time}"")
    return streams

def thread_task(rx_ue_info_tag):
    num_pdus = 5
    num_streams = 3

    pdus = generate_nfa_crc_pdu(rx_ue_info_tag, num_pdus)
    streams = generate_sdr_rx_stream(rx_ue_info_tag, num_streams)

    # Placeholder for further processing or storing results

def main():
    rx_ue_tags = range(1, 11)  # Example: 10 UE tags
    threads = []

    try:
        for tag in rx_ue_tags:
            thread = Thread(target=thread_task, args=(tag,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()
    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()

# Unit tests
import unittest

class TestEntityGeneration(unittest.TestCase):
    def test_nfa_crc_pdu_creation(self):
        rx_ue_info_tag = 1
        pdus = generate_nfa_crc_pdu(rx_ue_info_tag, 10)
        self.assertEqual(len(pdus), 10)
        for _, pdu in pdus:
            self.assertTrue(RNTI_RANGE_START <= pdu.RNTI <= RNTI_RANGE_END)

    def test_sdr_rx_stream_creation(self):
        rx_ue_info_tag = 1
        streams = generate_sdr_rx_stream(rx_ue_info_tag, 10)
        self.assertEqual(len(streams), 10)
        for _, stream in streams:
            self.assertTrue(SNR_MIN <= stream.SNR <= SNR_MAX)

if __name__ == ""__main__"":
    unittest.main()
