import json
import logging
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class MQTTManager:
    def __init__(self, broker_address=""localhost"", port=1883):
        self.client = mqtt.Client()
        self.broker_address = broker_address
        self.port = port
        self.subscriptions = set()

        # Setup callbacks
        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message

    def connect(self):
        try:
            self.client.connect(self.broker_address, self.port)
            self.client.loop_start()
        except Exception as e:
            logger.error(f""Failed to connect: {e}"")

    def subscribe(self, topic):
        if topic not in self.subscriptions:
            try:
                self.client.subscribe(topic)
                self.subscriptions.add(topic)
                logger.info(f""Subscribed to {topic}"")
            except Exception as e:
                logger.error(f""Error subscribing to {topic}: {e}"")

    def unsubscribe(self, topic):
        if topic in self.subscriptions:
            try:
                self.client.unsubscribe(topic)
                self.subscriptions.remove(topic)
                logger.info(f""Unsubscribed from {topic}"")
            except Exception as e:
                logger.error(f""Error unsubscribing from {topic}: {e}"")

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            logger.info(""Connected to MQTT Broker"")
            self.subscribe_to_all()
        else:
            logger.error(f""Failed to connect, return code {rc}"")

    def subscribe_to_all(self):
        for topic in self.subscriptions:
            self.client.subscribe(topic)

    def on_message(self, client, userdata, msg):
        try:
            message_json = json.loads(msg.payload.decode('utf-8'))
            self.process_message(msg.topic, message_json)
        except Exception as e:
            logger.error(f""Error processing message from {msg.topic}: {e}"")

    def process_message(self, topic, message):
        # Define your rules and actions here
        if ""some_key"" in message:
            self.handle_specific_rule(message)

    def handle_specific_rule(self, message):
        # Example action based on message content
        logger.info(f""Handling specific rule for message: {message}"")

# Usage example
if __name__ == ""__main__"":
    mqtt_manager = MQTTManager()
    mqtt_manager.connect()

    # Subscribe to topics dynamically
    mqtt_manager.subscribe(""test/topic1"")
    mqtt_manager.subscribe(""test/topic2"")

    try:
        while True:
            pass  # Keep the main thread alive
    except KeyboardInterrupt:
        logger.info(""Exiting program."")
