from flask import Flask, request, jsonify
import time
from sklearn.linear_model import LinearRegression  # Example ML model
import hashlib

app = Flask(__name__)
last_processed_time = None

class CArithmeticOps:
    def __init__(self):
        self.add_table = {}
        self.subtract_table = {}
        self.multiply_table = {}
        self.divide_table = {}

    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        if b != 0:
            return a / b
        else:
            raise ValueError(""Division by zero"")

def compute_md5_file(file_path):
    hasher = hashlib.md5()
    ops = CArithmeticOps()

    with open(file_path, 'rb') as file:
        while chunk := file.read(8192):  # Read in chunks to manage memory
            # Example usage of arithmetic operations on bytes
            result = ops.add(hasher.digest_size, len(chunk))
            hasher.update(chunk)

    return hasher.hexdigest()

@app.route('/process', methods=['POST'])
def process_data():
    global last_processed_time

    if last_processed_time and time.time() - last_processed_time < 9:
        return jsonify({'error': 'Cooldown period active'}), 429

    data = request.json
    # Example processing: Train a simple regression model
    model = LinearRegression()
    X, y = data['features'], data['target']
    model.fit(X, y)

    last_processed_time = time.time()

    return jsonify({'message': 'Data processed successfully'})

if __name__ == '__main__':
    app.run(debug=True)
