def process_input_stream(input_stream):
    def count_character_frequencies(stream):
        frequency_dict = {}
        for char in stream:
            if char.isalnum():
                frequency_dict[char] = frequency_dict.get(char, 0) + 1
        return frequency_dict

    def find_highest_frequency_character(frequency_dict):
        return max(frequency_dict, key=frequency_dict.get)

    character_frequencies = count_character_frequencies(input_stream)
    highest_freq_char = find_highest_frequency_character(character_frequencies)

    print(""Character with the highest frequency:"", highest_freq_char)
```

