class WeatherData:
    def __init__(self, location, temperature, humidity, pressure):
        self.location = location
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure

def determine_weather_condition(weather_data: WeatherData) -> str:
    # Extract the necessary information using attributes of WeatherData object.
    location = weather_data.location
    temperature = weather_data.temperature

    # Determine the current weather condition based on temperature and other factors if needed.
    if temperature > 30:
        condition = ""Hot""
    elif 20 <= temperature <= 30:
        condition = ""Warm""
    elif 10 <= temperature < 20:
        condition = ""Cool""
    else:
        condition = ""Cold""

    # Return a formatted string containing the location and its corresponding weather condition.
    return f""The current weather in {location} is {condition}.""
