```python
import sqlite3

def construct_sql_query(data_dict, table_name, column_names=None, conditions=None):
    if not isinstance(data_dict, dict) or not table_name:
        raise ValueError(""Invalid input format: data_dict must be a dictionary and table_name must be provided."")

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f""{parent_key}{sep}{k}"" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    def validate_columns(data_keys):
        if column_names and set(data_keys) != set(column_names):
            raise ValueError(""Mismatch between provided columns and data keys."")

    flattened_data = flatten_dict(data_dict)

    rows = []
    for record in flattened_data.values():
        validate_columns(record.keys())
        columns_part = ', '.join(record.keys())
        placeholders = ', '.join(['?'] * len(record))
        values_part = tuple(record.values())
        rows.append((columns_part, placeholders, values_part))

    sql_queries = []

    for columns_part, placeholders, values_part in rows:
        query_base = f""INSERT INTO {table_name} ({columns_part})""
        if conditions:
            condition_str = ' AND '.join([f""{k}=?"" for k in conditions.keys()])
            query_base += f"" WHERE {condition_str}""
            sql_queries.append((query_base + "" VALUES ("" + placeholders + ""))"", values_part + tuple(conditions.values()))
        else:
            sql_queries.append((query_base + "" VALUES ("" + placeholders + ""))"", values_part)

    return sql_queries

def execute_sql(db_path, queries):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    try:
        for query, params in queries:
            cursor.execute(query, params)
        conn.commit()
    except Exception as e:
        print(f""An error occurred: {e}"")
        conn.rollback()
    finally:
        conn.close()

# Unit tests
def test_construct_sql_query():
    data = {
        'id': 1,
        'name': 'John Doe',
        'address': {'city': 'New York', 'zipcode': '10001'}
    }

    queries = construct_sql_query(data, 'users')
    expected_queries = [
        (""INSERT INTO users (id,name,address.city,address.zipcode) VALUES (?, ?, ?, ?)"", (1, 'John Doe', 'New York', '10001'))
    ]
    assert queries == expected_queries, f""Expected {expected_queries}, but got {queries}""

    data_with_conditions = {
        'id': 2,
        'name': 'Jane Smith',
        'address': {'city': 'Los Angeles', 'zipcode': '90001'}
    }

    queries_with_conditions = construct_sql_query(data_with_conditions, 'users', conditions={'id': 1})
    expected_queries_with_conditions = [
        (""INSERT INTO users (id,name,address.city,address.zipcode) VALUES (?, ?, ?, ?) WHERE id=?"", (2, 'Jane Smith', 'Los Angeles', '90001', 1))
    ]
    assert queries_with_conditions == expected_queries_with_conditions, f""Expected {expected_queries_with_conditions}, but got {queries_with_conditions}""

test_construct_sql_query()
```

