import sqlite3
from typing import Optional

def manage_user_session(user_id: str, action: str, data: dict = None):
    # Connect to the database
    conn = sqlite3.connect('sessions.db')
    cursor = conn.cursor()

    try:
        # Retrieve session data for the user
        cursor.execute(""SELECT session_data FROM sessions WHERE user_id = ?"", (user_id,))
        result = cursor.fetchone()

        if not result:
            print(f""No session found for user {user_id}."")
            return

        session_data = result[0]
        if not session_data:
            session_data = {}

        # Load session data as a dictionary
        if isinstance(session_data, str):
            session_data = eval(session_data)
        elif not isinstance(session_data, dict):
            session_data = {}

        # Update the session based on action
        if action == ""add_to_cart"":
            item_id = data.get(""item_id"")
            if item_id:
                cart = session_data.get(""cart"", [])
                cart.append(item_id)
                session_data[""cart""] = cart

        elif action == ""remove_from_cart"":
            item_id = data.get(""item_id"")
            if item_id and ""cart"" in session_data:
                session_data[""cart""].remove(item_id)

        elif action == ""login"":
            auth_details = data.get(""auth_details"")
            if auth_details:
                session_data.update(auth_details)

        elif action == ""logout"":
            session_data.clear()

        # Store the updated session back into the database
        cursor.execute(
            ""UPDATE sessions SET session_data = ? WHERE user_id = ?"",
            (str(session_data), user_id)
        )

    except sqlite3.Error as e:
        print(f""Database error: {e}"")

    finally:
        conn.commit()
        conn.close()

# Example usage
manage_user_session(""user123"", ""add_to_cart"", {""item_id"": 101})
