import uuid
import random
import time
from queue import Queue

def create_job_submission_list(num_jobs, min_time, max_time):
    def generate_unique_id():
        return str(uuid.uuid4())

    def estimate_execution_time():
        return random.uniform(min_time, max_time)

    job_submissions = []
    queue = Queue()

    for _ in range(num_jobs):
        job_id = generate_unique_id()
        while job_id in [job['job_id'] for job in job_submissions]:
            job_id = generate_unique_id()

        priority = random.randint(1, 100)
        execution_time = estimate_execution_time()

        new_job_submission = {
            'job_id': job_id,
            'priority': priority,
            'execution_time': execution_time,
            'created_at': int(time.time())
        }

        time.sleep(execution_time)

        queue.put(new_job_submission)

    return [job for job in queue.queue]
