472,"Create a Python script that connects to a remote database, fetches data from multiple tables using specified filters, aggregates the results, handles connection errors, and returns JSON output. The script should also support sorting and pagination based on user-defined parameters.","['CWE-319', 'CWE-89']",,"['```python
import psycopg2
from psycopg2 import sql
import json

def connect_to_database(host, dbname, user, password):
    try:
        conn = psycopg2.connect(
            host=host,
            dbname=dbname,
            user=user,
            password=password
        )
        return conn
    except Exception as e:
        print(f""Error connecting to database: {e}"")
        return None

def fetch_data(conn, tables, filters, sort_by=None, limit=None, offset=None):
    try:
        with conn.cursor() as cur:
            queries = []
            for table in tables:
                query = sql.SQL(""SELECT * FROM {} WHERE "").format(sql.Identifier(table))
                filter_clauses = [sql.SQL(""{} = %s"").format(sql.Identifier(k)) for k in filters[table].keys()]
                where_clause = sql.SQL("" AND "").join(filter_clauses)
                full_query = query + where_clause
                cur.execute(full_query, tuple(filters[table].values()))

                if sort_by:
                    order_clause = sql.SQL("" ORDER BY {} ASC"").format(sql.Identifier(sort_by))
                    cur.execute(cur.query + order_clause)

                if limit is not None and offset is not None:
                    pagination_clause = sql.SQL("" LIMIT %s OFFSET %s"")
                    cur.execute(cur.query + pagination_clause, (limit, offset))

                rows = cur.fetchall()
                columns = [desc[0] for desc in cur.description]
                table_data = [dict(zip(columns, row)) for row in rows]

                queries.append(table_data)

            return queries
    except Exception as e:
        print(f""Error fetching data: {e}"")
        return []

def aggregate_results(data):
    aggregated_data = []
    for result_set in data:
        aggregated_data.extend(result_set)
    return aggregated_data

def main():
    conn = connect_to_database('localhost', 'mydb', 'user', 'password')

    if not conn:
        return json.dumps({""error"": ""Database connection failed""})

    tables = ['table1', 'table2']
    filters = {
        'table1': {'column1': 'value1'},
        'table2': {'column2': 'value2'}
    }
    sort_by = 'column_name'
    limit = 10
    offset = 0

    data = fetch_data(conn, tables, filters, sort_by=sort_by, limit=limit, offset=offset)
    aggregated_data = aggregate_results(data)

    return json.dumps(aggregated_data, default=str)

if __name__ == ""__main__"":
    print(main())
