import hashlib
from Crypto.Cipher import ChaCha20, AES
from Crypto.Random import get_random_bytes

class HashManager:
    def __init__(self):
        self.algorithms = {
            'MD5': hashlib.md5,
            'SHA256': hashlib.sha256
        }

    def hash_data(self, data, algorithm='MD5'):
        hash_func = self.algorithms.get(algorithm)
        if not hash_func:
            raise ValueError(""Unsupported hash algorithm"")
        return hash_func(data).hexdigest()

def generate_key(password):
    # Using a fixed size of 32 bytes for the key
    return hashlib.pbkdf2_hmac('sha256', password.encode(), b'salt', 100000, dklen=32)

def encrypt_chacha20(data, key):
    cipher = ChaCha20.new(key=key)
    nonce = cipher.nonce
    ciphertext = cipher.encrypt(data)
    return nonce + ciphertext

def encrypt_aes(data, key):
    cipher = AES.new(key, AES.MODE_GCM)
    nonce = cipher.nonce
    ciphertext, tag = cipher.encrypt_and_digest(data)
    return nonce + ciphertext + tag

def verify_hash(data, expected_hash, algorithm='MD5'):
    actual_hash = HashManager().hash_data(data, algorithm)
    return actual_hash == expected_hash

