from Crypto.Cipher import AES
from Crypto.Hash import SHA1
from Crypto import Random
import struct

class CipherCtx:
    def __init__(self, password):
        self.password = password
        self.salt = Random.new().read(16)
        self.key = self.derive_key()
        self.iv = Random.new().read(AES.block_size)
        self.cipher = AES.new(self.key, AES.MODE_CBC, self.iv)

    def derive_key(self):
        hasher = SHA1.new()
        hasher.update(self.password.encode('utf-8') + self.salt)
        return hasher.digest()[:16]

    def pad(self, data):
        padding_length = AES.block_size - len(data) % AES.block_size
        return data + (chr(padding_length) * padding_length).encode()

    def encrypt(self, data):
        padded_data = self.pad(data.encode())
        return self.iv + self.cipher.encrypt(padded_data)


