import random

def generate_unique_sequences(num_sequences, num_zeros, max_length):
    def is_unique(sequence, existing_sequences):
        return sequence not in existing_sequences

    def generate_sequence(length, num_zeros):
        if length < num_zeros or (length - num_zeros) < 0:
            raise ValueError(""Invalid number of zeros for the given length."")

        sequence = ['1'] * (length - num_zeros) + ['0'] * num_zeros
        random.shuffle(sequence)
        return ''.join(sequence)

    existing_sequences = set()
    sequences = []

    while len(sequences) < num_sequences:
