import pandas as pd
from sklearn.linear_model import LinearRegression
import numpy as np
import threading
import time
import logging

# Set up logging
logging.basicConfig(filename='system.log', level=logging.INFO, format='%(asctime)s:%(levelname)s:%(message)s')

class SensorData:
    def __init__(self):
        self.data = pd.DataFrame(columns=['timestamp', 'temperature', 'humidity', 'energy_usage'])

    def add_reading(self, timestamp, temperature, humidity, energy_usage):
        new_data = {'timestamp': timestamp, 'temperature': temperature,
                    'humidity': humidity, 'energy_usage': energy_usage}
        self.data = self.data.append(new_data, ignore_index=True)

    def get_latest_readings(self):
        return self.data.tail(1).to_dict('records')

class EnergyPredictor:
    def __init__(self):
        self.model = LinearRegression()

    def train_model(self, data):
        # Prepare the dataset
        X = data[['temperature', 'humidity']]
        y = data['energy_usage']
        self.model.fit(X, y)

    def predict_energy_usage(self, temperature, humidity):
        return self.model.predict(np.array([[temperature, humidity]]))[0]

class DecisionMaker:
    def __init__(self):
        self.current_settings = {}

    def make_decision(self, predicted_usage, current_usage):
        if predicted_usage > current_usage * 1.2:  # Threshold for making adjustments
            adjustment = 'decrease'
        elif predicted_usage < current_usage * 0.8:
            adjustment = 'increase'
        else:
            adjustment = 'maintain'

        self.log_decision(adjustment, predicted_usage)
        return adjustment

    def log_decision(self, decision, prediction):
        logging.info(f""Decision made: {decision}, Prediction: {prediction}"")

class DataStream:
    def __init__(self, sensor_data, energy_predictor, decision_maker):
        self.sensor_data = sensor_data
        self.energy_predictor = energy_predictor
        self.decision_maker = decision_maker

    def start_streaming(self):
        while True:
            # Simulate real-time data streaming with a sleep
            current_readings = self.sensor_data.get_latest_readings()
            if current_readings:
                latest_reading = current_readings[0]
                predicted_usage = self.energy_predictor.predict_energy_usage(
                    latest_reading['temperature'], latest_reading['humidity'])
                decision = self.decision_maker.make_decision(predicted_usage, latest_reading['energy_usage'])

                print(f""Decision: {decision}, Predicted Usage: {predicted_usage}"")
            time.sleep(5)  # Adjust the frequency of data streaming as needed

class UserInterface:
    def __init__(self):
        pass

    def display_data(self, sensor_data, prediction, decision):
        print(""Current Readings:"")
        for key, value in sensor_data.items():
            print(f""{key}: {value}"")
        print(f""Predicted Energy Usage: {prediction}"")
        print(f""Decision: {decision}"")

# Example usage
sensor_data = SensorData()
energy_predictor = EnergyPredictor()
decision_maker = DecisionMaker()

# Simulate adding data and training the model
for i in range(10):
    sensor_data.add_reading(time.time(), np.random.uniform(18, 26), 
                            np.random.uniform(30, 50), np.random.uniform(1.0, 3.5))
energy_predictor.train_model(sensor_data.data)

data_stream = DataStream(sensor_data, energy_predictor, decision_maker)
user_interface = UserInterface()

# Start streaming data
streaming_thread = threading.Thread(target=data_stream.start_streaming)
streaming_thread.daemon = True
streaming_thread.start()
