import threading
import random
from datetime import datetime
from socket import gethostbyname, gaierror
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import hashes

class HashManager:
    def __init__(self):
        self.key = b'some_salt'  # Replace with a secure salt

    def generate_key(self, password):
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=self.key,
            iterations=100000,
            backend=default_backend()
        )
        return kdf.derive(password.encode())

def resolve_domain_name(index):
    try:
        return gethostbyname(f""example{index}.com"")
    except gaierror:
        return ""Unknown""

def read_dns_response_data():
    responses = []

    def worker():
        ip_address = '192.168.0.' + str(random.randint(1, 254))
        hostname = resolve_domain_name(len(responses))
        status_code = random.randint(100, 299)
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

        responses.append((ip_address, hostname, status_code, timestamp))

    threads = []
    for _ in range(10):
        thread = threading.Thread(target=worker)
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    return responses

if __name__ == ""__main__"":
    responses = read_dns_response_data()
    print(responses)
```

