class RLCManager:
    def __init__(self, enc_alg_manager):
        self.enc_alg_manager = enc_alg_manager
        self.rlc_entities = {}

    def create_rlc_entity(self, pci, rnti, encryption_algorithm):
        if not self.enc_alg_manager.is_algorithm_supported(encryption_algorithm):
