import csv
import sys

def validate_data(row, rules):
    for rule in rules:
        col, condition, value = rule.split(':')
        col = int(col) - 1
        value = int(value)
        if condition == 'eq' and row[col] != value:
            return False
        elif condition == 'gt' and row[col] <= value:
            return False
        elif condition == 'lt' and row[col] >= value:
            return False
    return True

def main(input_file, output_file, validation_rules):
    try:
        with open(input_file, 'r') as file_input, open(output_file, 'w', newline='') as file_output:
            reader = csv.reader(file_input)
            writer = csv.writer(file_output)

            headers = next(reader)
            writer.writerow(headers)

            for row in reader:
                if validate_data(row, validation_rules):
                    writer.writerow(row)
    except FileNotFoundError as fnf_error:
        print(f""Error: {fnf_error}"")
    except Exception as e:
        print(f""An error occurred: {e}"")

def process_files(input_files_list, output_file_list, rules):
    for i in range(len(input_files_list)):
        input_filename = input_files_list[i]
        output_filename = output_file_list[i]
        validation_rules = rules[i]

        main(input_filename, output_filename, validation_rules)

if __name__ == '__main__':
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input.csv> <output.csv> <validation_rules>"")
    else:
        input_file = sys.argv[1]
        output_file = sys.argv[2]
        validation_rules = [rule.split(':') for rule in sys.argv[3].split(',')]

        main(input_file, output_file, validation_rules)
