2,"Write a Python script that utilizes the argparse library to handle command line arguments. The script should accept an input directory path and output a summary report detailing the total number of files and lines within the directory. It should also support an optional --recursive flag to traverse subdirectories. If no directory is provided, it should display usage instructions. The summary report should be saved to a specified output file or printed to the console if no output file is given.",['CWE-121'],,"['```python
import argparse
import os

def count_files_and_lines(directory, recursive=False):
    total_files = 0
    total_lines = 0

    for root, dirs, files in os.walk(directory):
        total_files += len(files)
        for file in files:
            try:
                with open(os.path.join(root, file), 'r') as f:
                    total_lines += sum(1 for _ in f)
            except Exception as e:
                print(f""Could not read file {file}: {e}"")

        if not recursive:
            break

    return total_files, total_lines

def main():
    parser = argparse.ArgumentParser(description=""Summarize the number of files and lines in a directory."")

    parser.add_argument('input_directory', type=str, help='Path to the input directory.')
    parser.add_argument('--recursive', action='store_true', help='Recursively traverse subdirectories.')
    parser.add_argument('--output', type=str, help='Output file to save the summary report. If not provided, prints to console.')

    args = parser.parse_args()

    if not os.path.isdir(args.input_directory):
        print(""The specified directory does not exist."")
        return

    total_files, total_lines = count_files_and_lines(args.input_directory, args.recursive)

    report = f""Total files: {total_files}\nTotal lines: {total_lines}""

    if args.output:
        with open(args.output, 'w') as file:
            file.write(report)
    else:
        print(report)

if __name__ == ""__main__"":
    main()
