from PIL import Image
import hashlib
import os

class SecureImageProcessorMD5:
    def __init__(self, resize_dimensions=(800, 600)):
        self.resize_dimensions = resize_dimensions

    def load_image(self, image_path):
        try:
            return Image.open(image_path)
        except Exception as e:
            print(f""Error loading image: {e}"")
            return None

    def resize_image(self, image):
        try:
            if image is not None:
                original_width, original_height = image.size
                ratio = min(self.resize_dimensions[0] / original_width, self.resize_dimensions[1] / original_height)
                new_size = (int(original_width * ratio), int(original_height * ratio))
                return image.resize(new_size, Image.ANTIALIAS)
            else:
                print(""Invalid image input."")
        except Exception as e:
            print(f""Error resizing image: {e}"")
            return None

    def encrypt_image(self, image, filename):
        try:
            if image is not None:
                sha256 = hashlib.sha256()
                sha256.update(filename.encode('utf-8'))
                watermark_text = sha256.hexdigest()

                # Create a text overlay for the watermark
                watermark_image = Image.new(""RGBA"", image.size)
                draw = ImageDraw.Draw(watermark_image)
                font = ImageFont.load_default()
                text_width, text_height = draw.textsize(watermark_text, font=font)
                position = (image.width - text_width - 10, image.height - text_height - 10)
                draw.text(position, watermark_text, fill=""white"", font=font)

                # Combine the original image with the watermark
                combined_image = Image.alpha_composite(image.convert(""RGBA""), watermark_image)
                return combined_image
        except Exception as e:
            print(f""Error encrypting image: {e}"")
            return None

    def save_image(self, image, output_path):
        try:
            if image is not None:
                image.save(output_path)
        except Exception as e:
            print(f""Error saving image: {e}"")

    def calculate_md5_hash(self, file_path, chunk_size=4096):
        try:
            md5 = hashlib.md5()
            with open(file_path, 'rb') as f:
                while chunk := f.read(chunk_size):
                    md5.update(chunk)
            return md5.hexdigest()
        except Exception as e:
            print(f""Error calculating MD5 hash: {e}"")
            return None

# Usage example
processor = SecureImageProcessorMD5()
image_path = ""example.jpg""
output_path = ""processed_image.png""

# Load, resize, encrypt with watermark, and save the image
image = processor.load_image(image_path)
resized_image = processor.resize_image(image)
watermarked_image = processor.encrypt_image(resized_image, os.path.basename(image_path))
processor.save_image(watermarked_image, output_path)

# Calculate MD5 hash of the saved file
md5_hash = processor.calculate_md5_hash(output_path)
print(f""MD5 Hash: {md5_hash}"")
```

